import{_ as t,o as i,c as a,ae as h}from"./chunks/framework.BONZgKEB.js";const m=JSON.parse('{"title":"Quản lý Sự kiện","description":"","frontmatter":{},"headers":[],"relativePath":"vi/guide/event-management.md","filePath":"vi/guide/event-management.md"}'),c={name:"vi/guide/event-management.md"};function g(o,n,e,u,r,l){return i(),a("div",null,[...n[0]||(n[0]=[h('<h1 id="quan-ly-su-kien" tabindex="-1">Quản lý Sự kiện <a class="header-anchor" href="#quan-ly-su-kien" aria-label="Permalink to &quot;Quản lý Sự kiện&quot;">​</a></h1><p>Hướng dẫn này bao gồm các bước tạo ban đầu và cấu hình một sự kiện bắn cung sử dụng ứng dụng <strong>Quản lý Sự kiện Bắn cung</strong>.</p><h2 id="_1-tao-mot-su-kien-moi" tabindex="-1">1. Tạo một Sự kiện Mới <a class="header-anchor" href="#_1-tao-mot-su-kien-moi" aria-label="Permalink to &quot;1. Tạo một Sự kiện Mới&quot;">​</a></h2><p>Để tổ chức một sự kiện mới, trước tiên bạn phải tạo nó thông qua bảng điều khiển ứng dụng.</p><ol><li>Điều hướng đến phần <strong>Sự kiện</strong> trên thanh điều hướng chính.</li><li>Nhấp vào nút <strong>Tạo Sự kiện</strong>.</li><li>Điền các thông tin chi tiết được yêu cầu: <ul><li><strong>Tên Sự kiện:</strong> Một tên rõ ràng, dễ nhận biết cho cuộc thi của bạn.</li><li><strong>Ngày:</strong> Chọn ngày bắt đầu và ngày kết thúc.</li><li><strong>Địa điểm:</strong> Nơi sẽ diễn ra sự kiện.</li><li><strong>Luật lệ:</strong> Xác định luật điều hành (ví dụ: WA - Bắn cung Thế giới).</li></ul></li><li>Nhấp vào <strong>Gửi</strong> để tạo sự kiện.</li></ol><p>Sau khi được tạo, bạn sẽ được chuyển hướng đến <strong>Bảng điều khiển Sự kiện</strong>, còn được gọi là <strong>Bảng điều khiển của Ban Tổ chức (Host Panel)</strong>.</p><h2 id="_2-bang-đieu-khien-cua-ban-to-chuc" tabindex="-1">2. Bảng điều khiển của Ban Tổ chức <a class="header-anchor" href="#_2-bang-đieu-khien-cua-ban-to-chuc" aria-label="Permalink to &quot;2. Bảng điều khiển của Ban Tổ chức&quot;">​</a></h2><p>Bảng điều khiển của Ban Tổ chức (<code>EventDetailView</code>) là phòng điều khiển trung tâm của bạn để quản lý vòng đời sự kiện. Nó cung cấp một số tab để quản lý các khía cạnh khác nhau của sự kiện của bạn:</p><h3 id="tong-quan" tabindex="-1">Tổng quan <a class="header-anchor" href="#tong-quan" aria-label="Permalink to &quot;Tổng quan&quot;">​</a></h3><p>Tab này hiển thị thông tin tổng quan về sự kiện, bao gồm trạng thái, ngày tháng và tổng số người tham gia.</p><h3 id="van-đong-vien" tabindex="-1">Vận động viên <a class="header-anchor" href="#van-đong-vien" aria-label="Permalink to &quot;Vận động viên&quot;">​</a></h3><p>Trước khi cuộc thi có thể bắt đầu, các vận động viên phải được đăng ký vào sự kiện.</p><ul><li>Sử dụng chức năng <strong>Đăng ký Vận động viên</strong> để thêm người tham gia.</li><li>Bạn có thể xem danh sách tất cả các vận động viên đã đăng ký, đội của họ và các hạng mục tương ứng của họ (ví dụ: Cung 1 dây Nam, Cung trợ lực Nữ).</li></ul><h3 id="trong-tai" tabindex="-1">Trọng tài <a class="header-anchor" href="#trong-tai" aria-label="Permalink to &quot;Trọng tài&quot;">​</a></h3><p>Trọng tài chịu trách nhiệm xác minh điểm số trong suốt sự kiện.</p><ul><li>Chỉ định người dùng có vai trò trọng tài cho sự kiện của bạn.</li><li>Chỉ các trọng tài đã đăng ký mới có quyền truy cập vào bảng điểm trong quá trình thi đấu.</li></ul><h3 id="cai-đat-cua-ban-to-chuc" tabindex="-1">Cài đặt của Ban Tổ chức <a class="header-anchor" href="#cai-đat-cua-ban-to-chuc" aria-label="Permalink to &quot;Cài đặt của Ban Tổ chức&quot;">​</a></h3><p>Tab này cung cấp các quyền kiểm soát quản trị:</p><ul><li><strong>Chỉnh sửa Chi tiết:</strong> Sửa đổi tên sự kiện, ngày tháng hoặc địa điểm.</li><li><strong>Tạo Cuộc thi:</strong> Dựa trên các vận động viên đã đăng ký, hệ thống có thể tự động phân nhóm họ vào các hạng mục thi đấu hợp lệ.</li></ul><h2 id="_3-chuyen-sang-thiet-lap-thi-đau" tabindex="-1">3. Chuyển sang Thiết lập Thi đấu <a class="header-anchor" href="#_3-chuyen-sang-thiet-lap-thi-đau" aria-label="Permalink to &quot;3. Chuyển sang Thiết lập Thi đấu&quot;">​</a></h2><p>Khi tất cả các vận động viên và trọng tài của bạn đã được đăng ký và chi tiết sự kiện của bạn đã được hoàn thiện, bạn đã sẵn sàng chuyển sang giai đoạn <strong>Thiết lập Thi đấu</strong>. Điều này bao gồm việc lên lịch các vòng Phân hạng và tạo sơ đồ đấu Loại.</p><p>👉 <em>Bước tiếp theo:</em> <a href="./competition-setup.html">Tìm hiểu cách thiết lập các cuộc thi của bạn</a></p>',22)])])}const k=t(c,[["render",g]]);export{m as __pageData,k as default};
